args.sparql:
SELECT ?person ?birthDate WHERE {
 VALUES ?person { dbr:Robert_G._Vignola dbr:Rob_Margolies }
 OPTIONAL { ?person dbo:birthDate ?birthDate . }
 OPTIONAL { ?person dbp:birth_date ?birthDate2 . }
 BIND(COALESCE(?birthDate, ?birthDate2) AS ?bd)
 FILTER(bound(?bd))
 BIND(?bd AS ?birthDate)
}

SELECT ?person (COALESCE(?bd1, ?bd2) AS ?birthDate) WHERE {
  VALUES ?person { dbr:Robert_G._Vignola dbr:Rob_Margolies }
  OPTIONAL { ?person dbo:birthDate ?bd1 . }
  OPTIONAL { ?person dbp:birth_date ?bd2 . }
}

SELECT ?olderFilm WHERE {
  VALUES (?film1 ?film2) { (<http://dbpedia.org/resource/Women%27s_Weapons> dbr:She_Wants_Me) }
  ?film1 (dbo:director|dbp:director) ?dir1 .
  ?film2 (dbo:director|dbp:director) ?dir2 .
  OPTIONAL { ?dir1 dbo:birthDate ?bd1 . }
  OPTIONAL { ?dir1 dbp:birth_date ?bd1b . }
  OPTIONAL { ?dir2 dbo:birthDate ?bd2 . }
  OPTIONAL { ?dir2 dbp:birth_date ?bd2b . }
  BIND(COALESCE(?bd1, ?bd1b) AS ?birth1)
  BIND(COALESCE(?bd2, ?bd2b) AS ?birth2)
  FILTER(bound(?birth1) && bound(?birth2) && (?birth1 < ?birth2))
  BIND(?film1 AS ?olderFilm)
}

